-- Additional annual audit and quality evidence controls from SWM Rules, 2026.
insert into regulatory_requirements (regulatory_source_id,code,stakeholder_class,requirement_type,obligation,evidence_requirements,reporting_frequency,external_system,external_url,notes)
select s.id,v.code,v.stakeholder_class,v.requirement_type,v.obligation,v.evidence_requirements::jsonb,v.reporting_frequency,v.external_system,v.external_url,v.notes
from regulatory_sources s join (values
('SWM-2026-SPCB-FACILITY-ANNUAL-AUDIT','STATE_POLLUTION_CONTROL_BOARD_OR_POLLUTION_CONTROL_COMMITTEE','WASTE_FACILITY_AUDIT','Track annual audit of authorized solid waste processing facilities and publication of audit reports.','["facility_registration_reference","authorization_reference","financial_year","auditor_identity","audit_report_hash","portal_publication_reference"]','ANNUAL_AUDIT_BY_30_SEPTEMBER_AND_PUBLICATION_BY_31_DECEMBER','CPCB Centralised Solid Waste Management Portal','https://swmp.cpcb.gov.in/en/','Rule 39(5)-(6) of S.O. 388(E). Evidence tracker only; RupayKg does not certify statutory audits.'),
('SWM-2026-ORGANIC-MANURE-MONTHLY-TEST-REPORT','SOLID_WASTE_PROCESSING_FACILITY','ORGANIC_MANURE_QUALITY_REPORTING','Track testing of organic manure and monthly upload of test reports by facility operators.','["facility_registration_reference","production_period","sample_collection_date","laboratory_identity","test_report_hash","portal_upload_reference"]','MONTHLY','CPCB Centralised Solid Waste Management Portal','https://swmp.cpcb.gov.in/en/','Rule 39(11)-(12) of S.O. 388(E). Store laboratory evidence and upload receipts; do not infer compliance from missing reports.'),
('SWM-2026-CPCB-PUBLIC-DASHBOARD-DATA','CENTRAL_POLLUTION_CONTROL_BOARD','PUBLIC_DATA_AVAILABILITY','Track evidence that the public dashboard exposes waste generated, collected, processed and landfilled at national, state and district levels, plus landfill and legacy dumpsite information.','["official_dashboard_URL","observation_timestamp","national_data_capture","state_data_capture","district_data_capture","landfill_inventory_capture","legacy_dumpsite_inventory_capture"]','CONTINUOUS_ASSURANCE','CPCB Centralised Solid Waste Management Portal','https://swmp.cpcb.gov.in/en/','Rule 16(2)-(3) of S.O. 388(E). Public dashboard availability is distinct from API access.')
) as v(code,stakeholder_class,requirement_type,obligation,evidence_requirements,reporting_frequency,external_system,external_url,notes) on true
where s.title='Solid Waste Management Rules, 2026' and s.reference='S.O. 388(E)'
on conflict (code) do update set obligation=excluded.obligation,evidence_requirements=excluded.evidence_requirements,reporting_frequency=excluded.reporting_frequency,external_url=excluded.external_url,notes=excluded.notes;
